    "audit_result": {
      "property_id": "PROP-6a4369e9-inv-014",
      "classification": "potential-vulnerability",
      "code_path": "consensus/types/src/chain_spec.rs::apply_to_chain_spec::L2311-2323",
      "proof_trace": "Config deserialization (apply_to_chain_spec) assigns fork epochs without validation. If config file contains out-of-order epochs (e.g., deneb_fork_epoch=100, capella_fork_epoch=200), fork_name_at_epoch() returns wrong fork at epoch 150, causing consensus divergence.",
      "attack_scenario": "Operator loads custom config with deneb_fork_epoch < capella_fork_epoch. At intermediate epochs, node applies wrong fork rules (e.g., Deneb logic instead of Capella), diverging from honest peers and potentially accepting invalid blocks.",
      "checklist_id": "PROP-6a4369e9-inv-014"
    },
    "text": "Fork epoch constants must be strictly ordered: GENESIS < ALTAIR < ... < ELECTRA < FULU.",
    "assertion": "GENESIS_FORK_EPOCH < ALTAIR_FORK_EPOCH < BELLATRIX_FORK_EPOCH < ... < FULU_FORK_EPOCH",
    "covers": "SG-001",
    "severity": "HIGH",
    "type": "invariant"
  }
}

